#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <sstream>
#include <iterator>

using namespace std;

class DataReader {
private:
    istream& reader;
    vector<string> tokens;
    size_t tokenIndex;

    void readTokens() {
        string line;
        if (getline(reader, line)) {
            istringstream iss(line);
            tokens = vector<string>(istream_iterator<string>(iss), istream_iterator<string>());
            tokenIndex = 0;
        } else {
            tokens.clear();
            tokenIndex = 0;
        }
    }

public:
    DataReader(istream& r) : reader(r), tokenIndex(0) {
        readTokens();
    }

    string next() {
        if (tokenIndex >= tokens.size()) {
            readTokens();
        }
        if (tokenIndex < tokens.size()) {
            return tokens[tokenIndex++];
        }
        return "";
    }

    string nextToken() {
        return next();
    }

    int nextInt() {
        return stoi(nextToken());
    }

    long long nextLong() {
        return stoll(nextToken());
    }

    vector<int> readIntArray(int n) {
        vector<int> result(n);
        for (int i = 0; i < n; ++i) {
            result[i] = nextInt();
        }
        return result;
    }

    string nextLine() {
        string line;
        getline(reader, line);
        return line;
    }
};

void solve(DataReader& reader, ostream& out) {
    int n = reader.nextInt();
    int k = reader.nextInt();
    string s = reader.nextToken();

    vector<bool> used(n, false);

    function<bool(int)> dfs = [&](int u) -> bool {
        if (u < 0 || u >= n || used[u] || s[u] == '#') return false;
        if (s[u] == 'T') return true;
        used[u] = true;

        return dfs(u - k) || dfs(u + k);
    };

    size_t gPos = s.find('G');
    out << (dfs(static_cast<int>(gPos)) ? "YES" : "NO") << endl;
}

int main() {
    istream* r;
    ostream* out;
    if (getenv("ONLINE_JUDGE") == nullptr) {
        ifstream* fileIn = new ifstream("input.txt");
        ofstream* fileOut = new ofstream("output.txt");
        r = fileIn;
        out = fileOut;
        DataReader reader(*r);
        solve(reader, *out);
        delete fileIn;
        delete fileOut;
    } else {
        cin.sync_with_stdio(false);
        DataReader reader(cin);
        solve(reader, cout);
    }

    return 0;
}

