#include <algorithm>
using namespace std;

class DataReader {
private:
    istream& in;
    vector<string> tokens;
    int tokenIndex;
    string line;

    void readLine() {
        if (in.eof()) return;
        getline(in, line);
        tokens.clear();
        tokenIndex = 0;
        size_t start = 0;
        size_t end = line.find(' ');
        while (end != string::npos) {
            tokens.push_back(line.substr(start, end - start));
            start = end + 1;
            end = line.find(' ', start);
        }
        tokens.push_back(line.substr(start));
    }

public:
    DataReader(istream& input) : in(input), tokenIndex(0) {
        readLine();
    }

    string nextToken() {
        if (tokenIndex >= tokens.size()) {
            readLine();
        }
        return tokens[tokenIndex++];
    }

    int nextInt() {
        return stoi(nextToken());
    }

    long long nextLong() {
        return stoll(nextToken());
    }

    string nextLine() {
        if (tokenIndex < tokens.size()) {
            string remaining;
            for (int i = tokenIndex; i < tokens.size(); ++i) {
                if (!remaining.empty()) remaining += " ";
                remaining += tokens[i];
            }
            tokenIndex = tokens.size();
            return remaining;
        }
        getline(in, line);
        return line;
    }
};

void solve(DataReader& reader, ostream& out) {
    int n = reader.nextInt();
    int k = reader.nextInt();
    string s = reader.nextToken();

    vector<bool> used(n, false);

    function<bool(int)> dfs = [&](int u) -> bool {
        if (u < 0 || u >= n || used[u] || s[u] == '#') return false;
        if (s[u] == 'T') return true;
        used[u] = true;
        return dfs(u - k) || dfs(u + k);
    };

    size_t gPos = s.find('G');
    out << (dfs(gPos) ? "YES" : "NO") << endl;
}

int main() {
    istream* in;
    ostream* out;
    #ifdef ONLINE_JUDGE
        in = &cin;
        out = &cout;
    #else
        ifstream* fileIn = new ifstream("input.txt");
        ofstream* fileOut = new ofstream("output.txt");
        in = fileIn;
        out = fileOut;
    #endif

    DataReader reader(*in);
    solve(reader, *out);
